import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BOeh4kYD.js";const u=JSON.parse('{"title":"About Digital Employee Works / 关于数字员工工场","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1790745464000}'),n={name:"about.md"};function i(l,e,s,p,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="about-digital-employee-works-关于数字员工工场" tabindex="-1">About Digital Employee Works / 关于数字员工工场 <a class="header-anchor" href="#about-digital-employee-works-关于数字员工工场" aria-label="Permalink to &quot;About Digital Employee Works / 关于数字员工工场&quot;">​</a></h1><p>Digital Employee Works is maintained by <strong>Zhu Wei / 朱卫 (joinwell52-AI)</strong> as an independent, engineering-driven production project.</p><p>数字员工工场由 <strong>朱卫（joinwell52-AI）</strong> 作为独立、工程驱动的生产项目持续维护。</p><h2 id="current-capability-当前能力" tabindex="-1">Current capability / 当前能力 <a class="header-anchor" href="#current-capability-当前能力" aria-label="Permalink to &quot;Current capability / 当前能力&quot;">​</a></h2><ul><li>Research Report Production Engine V1.3 / 研究报告生产机 V1.3</li><li>Research Runtime Center V4</li><li>Research Runtime Scheduler V2.0</li><li>Research Skills V2.0</li><li>Research Intelligence System V1.0</li></ul><p>The product is a ChatGPT-based Research Analyst Digital Employee with three intelligence pipelines, three permanent research columns, complete-report production at 15:00, release-only Publication at 20:00, and GitHub-verifiable work records.</p><p>该产品是一个通过 ChatGPT 实现的 Research Analyst 数字员工，具备三条研究情报管线、三个长期研究栏目、15:00 完整报告生产、20:00 只负责发版，以及可通过 GitHub 验证的工作记录。</p><h2 id="product-hierarchy-产品层级" tabindex="-1">Product hierarchy / 产品层级 <a class="header-anchor" href="#product-hierarchy-产品层级" aria-label="Permalink to &quot;Product hierarchy / 产品层级&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA + FCoP</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>CodeFlowMu + Digital Employee</span></span></code></pre></div><p>TMPA and FCoP appear in the first row of the website capability section. CodeFlowMu leads the second row, followed by Digital Employee.</p><p>网站能力区中，TMPA 与 FCoP 位于第一排；CodeFlowMu 位于第二排首位，随后是 Digital Employee。</p><p><strong>FCoP 4.0.5</strong> provides the MIT-licensed Python library and optional canonical MCP adapter: <strong>25 tools, 6 resources, and no resource templates</strong>. Core owns protocol facts, validation, and state transitions; MCP is a thin Core adapter. Runtime, Profile presets, Host configuration, and Legacy compatibility remain outside the Base Protocol. <a href="https://doi.org/10.5281/zenodo.23051275" target="_blank" rel="noreferrer">Software archive</a> · <a href="https://doi.org/10.5281/zenodo.22855630" target="_blank" rel="noreferrer">FCoP preprint 1.0</a> · <a href="https://github.com/joinwell52-AI/FCoP/blob/main/CITATION.cff" target="_blank" rel="noreferrer">FCoP citation metadata</a>. The paper&#39;s experiments and supplement use frozen 4.0.3; the 4.0.5 software update does not imply those experiments were rerun.</p><p><strong>FCoP 4.0.5</strong> 提供 MIT 开源 Python 库和可选的 Canonical MCP 适配器：<strong>25 个工具、6 个资源，无资源模板</strong>。Core 负责协议事实、验证和状态迁移；MCP 是 Core 的薄适配器。Runtime、Profile 预设、Host 配置和 Legacy 兼容均在 Base Protocol 之外。<a href="https://doi.org/10.5281/zenodo.23051275" target="_blank" rel="noreferrer">软件归档</a> · <a href="https://doi.org/10.5281/zenodo.22855630" target="_blank" rel="noreferrer">FCoP 预印本 1.0</a> · <a href="https://github.com/joinwell52-AI/FCoP/blob/main/CITATION.cff" target="_blank" rel="noreferrer">FCoP 引用元数据</a>。论文实验与补充材料使用冻结的 4.0.3 实现；4.0.5 软件更新不代表这些实验已重新运行。</p><h2 id="research-orientation-研究方向" tabindex="-1">Research orientation / 研究方向 <a class="header-anchor" href="#research-orientation-研究方向" aria-label="Permalink to &quot;Research orientation / 研究方向&quot;">​</a></h2><ul><li>Digital Employee positions, workflows, runtime, governance, and evaluation;</li><li>major AI-platform architecture and product evolution;</li><li>open-source agent runtime, protocol, SDK, recovery, evaluation, and observability;</li><li>AI work data and governance;</li><li>formal multi-agent coordination;</li><li>SME-first AI deployment.</li></ul><h2 id="method-方法" tabindex="-1">Method / 方法 <a class="header-anchor" href="#method-方法" aria-label="Permalink to &quot;Method / 方法&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI Platform + GitHub + Published Research intelligence</span></span>
<span class="line"><span>→ Three-column triage</span></span>
<span class="line"><span>→ Governed research lifecycle</span></span>
<span class="line"><span>→ Complete bilingual Publication Candidate</span></span>
<span class="line"><span>→ GitHub + website release</span></span>
<span class="line"><span>→ Runtime Record + Commit Verify</span></span></code></pre></div><p>Observation Notes record external developments and working judgments. They do not automatically become evidence for the TMPA paper.</p><p>观察笔记记录外部动态与工作判断，但不自动构成 TMPA 论文证据。</p><h2 id="download-下载" tabindex="-1">Download / 下载 <a class="header-anchor" href="#download-下载" aria-label="Permalink to &quot;Download / 下载&quot;">​</a></h2><ul><li><a href="./en/publications/research-report-production-engine-v1.3">Research Report Production Engine V1.3</a></li><li><a href="./zh/publications/research-report-production-engine-v1.3">研究报告生产机 V1.3</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/archive/refs/heads/main.zip" target="_blank" rel="noreferrer">Download source ZIP / 下载源码 ZIP</a></li></ul>`,21)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
